import ctypes as c
from ctypes import wintypes as w
import subprocess
import sys
import time
from pywinauto import Desktop,keyboard

class HC(c.Structure):
    _fields_=(("cbSize",w.UINT),("dwFlags",w.DWORD),("lpszDefaultScheme",w.LPWSTR))

u=c.WinDLL("user32",use_last_error=True)

def hc():
    x=HC()
    x.cbSize=c.sizeof(x)
    assert u.SystemParametersInfoW(0x0042,x.cbSize,c.byref(x),0)
    return bool(x.dwFlags&1),x.lpszDefaultScheme

def until(fn,label,seconds=30):
    end=time.monotonic()+seconds
    while time.monotonic()<end:
        try:
            v=fn()
            if v:
                return v
        except Exception:
            pass
        time.sleep(.25)
    raise AssertionError(label)

def settings():
    ws=[x for x in Desktop(backend="uia").windows() if x.window_text() in ("설정","Settings")]
    return ws[-1] if ws else None

def close_settings():
    for x in Desktop(backend="uia").windows():
        if x.window_text() in ("설정","Settings"):
            try:
                x.close()
            except Exception:
                pass
    time.sleep(1)

def named_list(*names):
    win=settings()
    if win is None:
        return None
    names=set(names)
    return next((e for e in win.descendants(control_type="ListItem")
                 if (e.window_text() or "").strip() in names),None)

def controls():
    win=settings()
    if win is None:
        return None
    combo=next((e for e in win.descendants(control_type="ComboBox") if e.is_visible()),None)
    apply=next((e for e in win.descendants(control_type="Button")
                if e.element_info.automation_id=="HighContrastThemeApplyButton"),None)
    return (combo,apply) if combo is not None and apply is not None else None

def open_contrast():
    close_settings()
    subprocess.Popen(["cmd","/c","start","","ms-settings:"])
    until(settings,"Settings missing")
    until(lambda:named_list("접근성","Accessibility"),"Accessibility nav missing").click_input()
    card=until(lambda:named_list("대비 테마","Contrast themes"),"Contrast card missing")
    card.set_focus()
    keyboard.send_keys("{ENTER}")
    return until(controls,"Contrast controls missing")

target=sys.argv[1].lower()=="on"
before,scheme=hc()
print("HC_FINAL_SETTINGS_BEFORE",target,before,repr(scheme),flush=True)
if before!=target:
    combo,apply=open_contrast()
    try:
        try:
            combo.select("밤하늘" if target else "없음")
        except Exception:
            combo.click_input()
            keyboard.send_keys("{END}{ENTER}" if target else "{HOME}{ENTER}")
        time.sleep(.5)
        apply.click_input()
        until(lambda:hc()[0]==target,"Contrast Apply did not reach target")
    finally:
        close_settings()
after,scheme=hc()
print("HC_FINAL_SETTINGS_AFTER",target,after,repr(scheme),flush=True)
if after!=target:
    raise SystemExit("Contrast target mismatch")

