from pathlib import Path
import ctypes as c
from ctypes import wintypes as w
import os,shutil,subprocess,sys,tempfile,time
import psutil
from PIL import ImageGrab
from pywinauto import Desktop

exe=Path(sys.argv[1]).resolve()
out=Path(sys.argv[2]).resolve()
out.mkdir(parents=True,exist_ok=True)
u=c.WinDLL("user32",use_last_error=True)
u.SetWindowPos.argtypes=(w.HWND,w.HWND,c.c_int,c.c_int,c.c_int,c.c_int,w.UINT)

class HC(c.Structure):
    _fields_=(("cbSize",w.UINT),("dwFlags",w.DWORD),("lpszDefaultScheme",w.LPWSTR))

def hc():
    x=HC()
    x.cbSize=c.sizeof(x)
    assert u.SystemParametersInfoW(0x0042,x.cbSize,c.byref(x),0)
    return bool(x.dwFlags&1)

def until(fn,label,seconds=15):
    end=time.monotonic()+seconds
    while time.monotonic()<end:
        try:
            if fn():
                return
        except Exception:
            pass
        time.sleep(.2)
    raise AssertionError(label)

assert hc()
owned=Path(tempfile.mkdtemp(prefix="hc-before-",dir=out))
folder=owned/"source"
folder.mkdir()
for name in ("contrast-alpha.txt","contrast-beta.txt","한국어-고대비.txt"):
    (folder/name).write_text("baseline",encoding="utf-8")

env=os.environ.copy()
for key in ("APPDATA","LOCALAPPDATA","TEMP","TMP"):
    d=owned/key.lower()
    d.mkdir()
    env[key]=str(d)

proc=subprocess.Popen([str(exe),str(folder)],cwd=exe.parent,env=env)
hwnd=None
passed=False
try:
    def ready():
        global hwnd
        if proc.poll() is not None:
            return False
        if Path(psutil.Process(proc.pid).exe()).resolve()!=exe:
            raise AssertionError("PID mismatch")
        ws=[x for x in Desktop(backend="uia").windows(process=proc.pid)
            if "flyExplorer" in x.window_text()]
        if len(ws)!=1:
            return False
        hwnd=ws[0].handle
        return ws[0].child_window(auto_id="LeftFiles").exists(timeout=.2)

    until(ready,"before window missing")
    win=Desktop(backend="uia").window(handle=hwnd)
    win.set_focus()
    assert u.SetWindowPos(hwnd,None,40,30,1100,720,0x0014)
    until(lambda:abs(win.rectangle().width()-1100)<=3,"before size mismatch")

    rows=[x for x in win.child_window(auto_id="LeftFiles").descendants()
          if x.element_info.control_type=="ListItem"]
    assert rows
    rows[0].select()
    time.sleep(.4)

    r=win.rectangle()
    ImageGrab.grab(
        bbox=(r.left,r.top,r.right,r.bottom),all_screens=True
    ).save(out/"high-contrast-before-shell.png")

    win.child_window(auto_id="SearchPanelButton").click_input()
    until(
        lambda:win.child_window(auto_id="SearchPanel").exists(timeout=.2)
        and win.child_window(auto_id="SearchPanel").is_visible(),
        "before search missing"
    )
    r=win.rectangle()
    ImageGrab.grab(
        bbox=(r.left,r.top,r.right,r.bottom),all_screens=True
    ).save(out/"high-contrast-before-search.png")
    assert hc()
    print("HIGH_CONTRAST_BEFORE_CAPTURE_PASS",True,flush=True)
    passed=True
finally:
    if proc.poll() is None:
        if hwnd is not None:
            u.PostMessageW(hwnd,0x10,0,0)
            try:
                proc.wait(timeout=10)
            except subprocess.TimeoutExpired:
                proc.terminate()
                proc.wait(timeout=5)
        else:
            proc.terminate()
            proc.wait(timeout=5)
    if passed and proc.returncode==0:
        shutil.rmtree(owned)

sys.exit(0 if passed and proc.returncode==0 else 1)

